PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE dim_geo (
	territory VARCHAR NOT NULL, 
	region VARCHAR NOT NULL, 
	PRIMARY KEY (territory)
);
CREATE TABLE dim_sku (
	sku_code VARCHAR NOT NULL, 
	category VARCHAR NOT NULL, 
	brand VARCHAR NOT NULL, 
	sku_name VARCHAR NOT NULL, 
	pack_size VARCHAR NOT NULL, 
	flavour VARCHAR NOT NULL, 
	tier VARCHAR NOT NULL, 
	base_mrp VARCHAR NOT NULL, 
	PRIMARY KEY (sku_code)
);
CREATE TABLE dim_rep (
	rep_id VARCHAR NOT NULL, 
	rep_name VARCHAR NOT NULL, 
	territory VARCHAR NOT NULL, 
	PRIMARY KEY (rep_id), 
	FOREIGN KEY(territory) REFERENCES dim_geo (territory)
);
CREATE TABLE dim_distributor (
	distributor_id VARCHAR NOT NULL, 
	distributor_name VARCHAR NOT NULL, 
	territory VARCHAR NOT NULL, 
	PRIMARY KEY (distributor_id), 
	FOREIGN KEY(territory) REFERENCES dim_geo (territory)
);
CREATE TABLE fact_targets (
	month DATE NOT NULL, 
	material_no VARCHAR NOT NULL, 
	area VARCHAR NOT NULL, 
	target_value FLOAT NOT NULL, 
	PRIMARY KEY (month, material_no, area), 
	FOREIGN KEY(material_no) REFERENCES dim_sku (sku_code), 
	FOREIGN KEY(area) REFERENCES dim_geo (territory)
);
CREATE TABLE promotions (
	week_start DATE NOT NULL, 
	sku VARCHAR NOT NULL, 
	territory VARCHAR NOT NULL, 
	promo_type VARCHAR NOT NULL, 
	promo_discount_pct FLOAT NOT NULL, 
	PRIMARY KEY (week_start, sku, territory), 
	FOREIGN KEY(sku) REFERENCES dim_sku (sku_code), 
	FOREIGN KEY(territory) REFERENCES dim_geo (territory)
);
CREATE TABLE stockouts (
	week_start DATE NOT NULL, 
	item_code VARCHAR NOT NULL, 
	territory VARCHAR NOT NULL, 
	stockout_flag VARCHAR NOT NULL, 
	stockout_days INTEGER NOT NULL, 
	PRIMARY KEY (week_start, item_code, territory), 
	FOREIGN KEY(item_code) REFERENCES dim_sku (sku_code), 
	FOREIGN KEY(territory) REFERENCES dim_geo (territory)
);
CREATE TABLE fact_primary_sales (
	week_start DATE NOT NULL, 
	sku_code VARCHAR NOT NULL, 
	territory VARCHAR NOT NULL, 
	distributor_id VARCHAR NOT NULL, 
	primary_sales_units INTEGER, 
	primary_sales_value FLOAT NOT NULL, 
	sales_units_flag VARCHAR NOT NULL, 
	PRIMARY KEY (week_start, sku_code, territory, distributor_id), 
	FOREIGN KEY(sku_code) REFERENCES dim_sku (sku_code), 
	FOREIGN KEY(territory) REFERENCES dim_geo (territory), 
	FOREIGN KEY(distributor_id) REFERENCES dim_distributor (distributor_id)
);
COMMIT;
